<?php
function ad_repo_staff_columns(){return implode(', ',['staff_id','staff_name','surname','alias','staff_nid','staff_nck_no','staff_email','staff_address','staff_photo','staff_id_imgback','staff_phone','whatsphone','staff_nssf','staff_nhif','staff_kra_pin','staff_kin_name','staff_kin_phone','staff_kin_id','staff_kin_relationship','staff_kin_relation','staff_kin_address','staff_kin_residence','staff_hire_date','staff_updated_date','staff_residence','staff_del_status','staff_user_status','staff_cv','staff_cv_status','staff_nid_img','staff_nid_img_status','staff_kin_id_image','staff_kin_id_image_status','staff_conduct_img','staff_conduct_img_status','emp_type','salary_cycle','salary_type','basic_salary','work_status']);}
function ad_repo_staff_where($filters=[]){global $connection;$where=[];if(empty($filters['include_deleted']))$where[]='staff_del_status = 2';$search=trim((string)($filters['search']??''));if($search!==''){$safe=mysqli_real_escape_string($connection,$search);$where[]="(staff_name LIKE '%{$safe}%' OR surname LIKE '%{$safe}%' OR alias LIKE '%{$safe}%' OR staff_phone LIKE '%{$safe}%' OR staff_email LIKE '%{$safe}%')";}return $where?'WHERE '.implode(' AND ',$where):'';}
function ad_repo_staff_count($filters=[]){global $connection;$result=mysqli_query($connection,'SELECT COUNT(*) AS total FROM kp_staff '.ad_repo_staff_where($filters));if(!$result)return 0;$row=mysqli_fetch_assoc($result);return (int)($row['total']??0);}
function ad_repo_staff_list($filters=[]){global $connection;$where=ad_repo_staff_where($filters);$limit=max(1,min(200,(int)($filters['limit']??50)));$offset=max(0,(int)($filters['offset']??0));$sql='SELECT '.ad_repo_staff_columns()." FROM kp_staff {$where} ORDER BY staff_id DESC LIMIT {$offset}, {$limit}";$result=mysqli_query($connection,$sql);if(!$result)return ['ok'=>false,'message'=>ad_db_error($connection),'rows'=>[]];$rows=[];while($row=mysqli_fetch_assoc($result))$rows[]=$row;return ['ok'=>true,'message'=>'Staff loaded.','rows'=>$rows];}
function ad_repo_staff($staff_id){global $connection;$staff_id=(int)$staff_id;$result=mysqli_query($connection,'SELECT '.ad_repo_staff_columns()." FROM kp_staff WHERE staff_id = {$staff_id} LIMIT 1");if(!$result)return ['ok'=>false,'message'=>ad_db_error($connection),'row'=>null];return ['ok'=>true,'message'=>'Staff loaded.','row'=>mysqli_fetch_assoc($result)?:null];}
function ad_repo_related($table,$staff_ids,$order=''){global $connection;$allowed=['kp_staff_nok','kp_staff_employment','kp_staff_employment_history','kp_staff_profile_checks','kp_staff_documents'];if(!in_array($table,$allowed,true)||!$staff_ids)return [];$ids=implode(',',array_map('intval',$staff_ids));$sql="SELECT * FROM {$table} WHERE staff_id IN ({$ids})".($order!==''?" ORDER BY {$order}":'');$result=mysqli_query($connection,$sql);if(!$result)return [];$rows=[];while($row=mysqli_fetch_assoc($result))$rows[]=$row;return $rows;}

function ad_repo_relationships(){global $connection;$result=mysqli_query($connection,"SELECT id,name FROM kp_relationship ORDER BY name ASC");if(!$result)return [];$rows=[];while($row=mysqli_fetch_assoc($result))$rows[]=['id'=>(int)$row['id'],'name'=>(string)$row['name']];return $rows;}
function ad_repo_roles(){global $connection;$result=mysqli_query($connection,"SELECT role_id,role_name,role_description,role_creation_date,role_last_update,role_access_panel,access_dash,front_perm FROM kp_roles ORDER BY role_name ASC");if(!$result)return [];$rows=[];while($row=mysqli_fetch_assoc($result))$rows[]=$row;return $rows;}
function ad_repo_role($role_id){global $connection;$role_id=(int)$role_id;$result=mysqli_query($connection,"SELECT role_id,role_name,role_description,role_creation_date,role_last_update,role_access_panel,access_dash,front_perm FROM kp_roles WHERE role_id={$role_id} LIMIT 1");return $result?mysqli_fetch_assoc($result):null;}
function ad_repo_role_save($data,$role_id=0){global $connection;$name=mysqli_real_escape_string($connection,(string)($data['role_name']??''));$description=mysqli_real_escape_string($connection,(string)($data['role_description']??''));$panel=(int)($data['role_access_panel']??0);$dash=(int)($data['access_dash']??0);$front=mysqli_real_escape_string($connection,(string)($data['front_perm']??''));if($role_id>0){$sql="UPDATE kp_roles SET role_name='{$name}',role_description='{$description}',role_access_panel={$panel},access_dash={$dash},front_perm='{$front}',role_last_update=NOW() WHERE role_id=".(int)$role_id;return mysqli_query($connection,$sql)?(int)$role_id:0;} $sql="INSERT INTO kp_roles (role_name,role_description,role_creation_date,role_last_update,role_access_panel,access_dash,front_perm) VALUES ('{$name}','{$description}',NOW(),NOW(),{$panel},{$dash},'{$front}')";if(!mysqli_query($connection,$sql))return 0;return (int)mysqli_insert_id($connection);}
function ad_repo_username_exists($username){global $connection;$safe=mysqli_real_escape_string($connection,$username);$result=mysqli_query($connection,"SELECT user_id FROM kp_users WHERE username='{$safe}' LIMIT 1");return $result&&mysqli_num_rows($result)>0;}
function ad_repo_insert_user($staff_id,$data){global $connection;$fields=['staff_id','username','password','pin','role_id','drole','sys_default','work_status'];$values=[(int)$staff_id];foreach(array_slice($fields,1) as $field){$value=$data[$field]??'';if(in_array($field,['role_id','drole','sys_default','work_status'],true))$values[]=(int)$value;else{$safe=mysqli_real_escape_string($connection,(string)$value);$values[]="'{$safe}'";}}$sql='INSERT INTO kp_users ('.implode(',',$fields).') VALUES ('.implode(',',$values).')';if(!mysqli_query($connection,$sql))return 0;return (int)mysqli_insert_id($connection);}
function ad_repo_users($search=''){global $connection;$where='';if($search!==''){$safe=mysqli_real_escape_string($connection,$search);$where="WHERE u.username LIKE '%{$safe}%' OR s.staff_name LIKE '%{$safe}%' OR s.surname LIKE '%{$safe}%'";}$sql="SELECT u.user_id,u.staff_id,u.username,u.role_id,u.drole,CASE WHEN u.user_work_status IN (1,2) THEN u.user_work_status ELSE u.work_status END AS work_status,u.permissions,u.max_sale,r.role_name,r.role_access_panel,s.staff_name,s.surname FROM kp_users u LEFT JOIN kp_roles r ON r.role_id=u.role_id LEFT JOIN kp_staff s ON s.staff_id=u.staff_id {$where} ORDER BY u.user_id DESC";$result=mysqli_query($connection,$sql);if(!$result)return [];$rows=[];while($row=mysqli_fetch_assoc($result))$rows[]=$row;return $rows;}
function ad_repo_user($user_id){global $connection;$result=mysqli_query($connection,"SELECT u.*,r.role_name,r.role_access_panel,s.staff_name,s.surname FROM kp_users u LEFT JOIN kp_roles r ON r.role_id=u.role_id LEFT JOIN kp_staff s ON s.staff_id=u.staff_id WHERE u.user_id=".(int)$user_id.' LIMIT 1');return $result?mysqli_fetch_assoc($result):null;}
function ad_repo_update_user($user_id,$data){global $connection;$sets=[];foreach(['username','role_id','drole'] as $field){$value=$data[$field]??'';$sets[]=$field==='username'?"username='".mysqli_real_escape_string($connection,$value)."'":"{$field}=".(int)$value;}return mysqli_query($connection,'UPDATE kp_users SET '.implode(',',$sets).' WHERE user_id='.(int)$user_id);}
function ad_repo_update_user_credential($user_id,$column,$value){global $connection;if(!in_array($column,['password','pin'],true))return false;$safe=mysqli_real_escape_string($connection,$value);return mysqli_query($connection,"UPDATE kp_users SET {$column}='{$safe}' WHERE user_id=".(int)$user_id);}
function ad_repo_update_user_target($user_id,$amount){global $connection;return mysqli_query($connection,"UPDATE kp_users SET max_sale=".(float)$amount.' WHERE user_id='.(int)$user_id);}
function ad_repo_update_permissions($user_id,$permissions){global $connection;$safe=mysqli_real_escape_string($connection,implode(', ',array_map('intval',$permissions)));return mysqli_query($connection,"UPDATE kp_users SET permissions='{$safe}' WHERE user_id=".(int)$user_id);}
function ad_repo_user_status($user_id,$status){global $connection;$status=(int)$status;$result=mysqli_query($connection,"UPDATE kp_users SET work_status={$status},user_work_status={$status} WHERE user_id=".(int)$user_id);return $result;}
function ad_repo_user_discipline($user_id,$reason,$actor_id=0){global $connection;$safe=mysqli_real_escape_string($connection,$reason);$actor=(int)$actor_id;$sql="INSERT INTO kp_displinary (user_id,reason,day) VALUES (".(int)$user_id.",'{$safe}',CURRENT_DATE)";return mysqli_query($connection,$sql);}
function ad_repo_permission_items(){global $connection;$result=mysqli_query($connection,'SELECT menu_id,name,parent,menu_order FROM kp_menu ORDER BY menu_order,menu_id');if(!$result)return [];$rows=[];while($row=mysqli_fetch_assoc($result))$rows[]=$row;return $rows;}

function ad_repo_insert_staff($data){global $connection;$fields=['staff_name','surname','alias','staff_nid','staff_email','staff_address','staff_phone','whatsphone','staff_nssf','staff_nhif','staff_kra_pin','staff_residence','staff_del_status','staff_user_status','staff_hire_date','work_status','salary_cycle','salary_type','basic_salary'];$columns=[];$values=[];foreach($fields as $field){$columns[]="`{$field}`";$value=$data[$field]??'';if($field==='staff_del_status'||$field==='staff_user_status')$values[]=(int)$value;elseif($field==='basic_salary')$values[]=$value===''?'NULL':(float)$value;else{$safe=mysqli_real_escape_string($connection,(string)$value);$values[]="'{$safe}'";}}$sql='INSERT INTO kp_staff ('.implode(',',$columns).') VALUES ('.implode(',',$values).')';if(!mysqli_query($connection,$sql))return 0;return (int)mysqli_insert_id($connection);}

function ad_repo_insert_nok($staff_id,$data){global $connection;$fields=['staff_id','nok_name','nok_phone','nok_id_number','nok_relationship','nok_address','nok_residence','is_current'];$values=[(int)$staff_id];foreach(array_slice($fields,1) as $field){$value=$field==='is_current'?1:(string)($data[$field]??'');$values[]=($field==='is_current')?(int)$value:"'".mysqli_real_escape_string($connection,$value)."'";}return mysqli_query($connection,'INSERT INTO kp_staff_nok ('.implode(',',$fields).') VALUES ('.implode(',',$values).')');}

function ad_repo_insert_employment($staff_id,$data){global $connection;$fields=['staff_id','department_name','job_title','employment_type','contract_type','work_status','start_date','hire_date','probation_end_date','contract_end_date','supervisor_name','notes','is_current'];$values=[(int)$staff_id];foreach(array_slice($fields,1) as $field){$value=$data[$field]??'';if($field==='is_current')$values[]='1';else{$safe=mysqli_real_escape_string($connection,(string)$value);$values[]=$value===''?'NULL':"'{$safe}'";}}return mysqli_query($connection,'INSERT INTO kp_staff_employment ('.implode(',',$fields).') VALUES ('.implode(',',$values).')');}

function ad_repo_insert_document($staff_id,$data){global $connection;$fields=['staff_id','doc_code','doc_title','file_name','file_path','file_ext','mime_type','file_size','is_current','uploaded_by','uploaded_at'];$values=[(int)$staff_id];foreach(array_slice($fields,1) as $field){$value=$data[$field]??'';if($field==='file_size'||$field==='uploaded_by'||$field==='is_current')$values[]=(int)$value;else{$safe=mysqli_real_escape_string($connection,(string)$value);$values[]=$value===''?'NULL':"'{$safe}'";}}return mysqli_query($connection,'INSERT INTO kp_staff_documents ('.implode(',',$fields).') VALUES ('.implode(',',$values).')');}
function ad_repo_update_staff_file($staff_id,$column,$path){global $connection;$allowed=['staff_photo','staff_nid_img','staff_cv','staff_conduct_img','staff_kin_id_image'];if(!in_array($column,$allowed,true))return false;$safe=mysqli_real_escape_string($connection,$path);return mysqli_query($connection,"UPDATE kp_staff SET `{$column}`='{$safe}' WHERE staff_id=".(int)$staff_id);}
